import math


def check_allocation(original, fragments, metric):
    if not isinstance(metric, str):
        raise TypeError("metric must be a string")
    if not metric:
        raise ValueError("metric must not be empty")
    if not isinstance(original, list) or not isinstance(fragments, list):
        raise TypeError("data arguments must be lists")

    totals = {}
    for record in original:
        if not isinstance(record, dict):
            raise TypeError("original records must be dictionaries")
        if set(record) != {"id", metric}:
            raise ValueError("malformed original record")
        identifier = record["id"]
        try:
            hash(identifier)
        except TypeError as exc:
            raise TypeError("identifiers must be hashable") from exc
        if identifier in totals:
            raise ValueError("duplicate original identifier")
        value = record[metric]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("metric values must be numbers")
        if not math.isfinite(value):
            raise ValueError("metric values must be finite")
        totals[identifier] = [value, 0.0, False]

    for record in fragments:
        if not isinstance(record, dict):
            raise TypeError("fragments must be dictionaries")
        if set(record) != {"source_id", metric}:
            raise ValueError("malformed fragment")
        identifier = record["source_id"]
        try:
            hash(identifier)
        except TypeError as exc:
            raise TypeError("identifiers must be hashable") from exc
        value = record[metric]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("metric values must be numbers")
        if not math.isfinite(value):
            raise ValueError("metric values must be finite")
        if identifier not in totals:
            raise AssertionError("fragment names an unknown identifier")
        totals[identifier][1] += value
        totals[identifier][2] = True

    for expected, actual, covered in totals.values():
        if not covered:
            raise AssertionError("an original identifier has no fragments")
        limit = abs(expected) * 0.001 if expected != 0 else 1e-12
        if abs(expected - actual) >= limit:
            raise AssertionError("fragment total is outside tolerance")
    return None

